import React, { useState } from 'react';

function Chatbot() {
  const [open, setOpen] = useState(false);
  const chatbotUrl = "https://agent.jotform.com/019902f7bce27a5e85010e43b3d62d4bdce4";

  return (
    <>
      {/* Floating button to open chatbot */}
      <button
        className="chatbot-toggle-btn"
        onClick={() => setOpen(!open)}
        style={{
          position: 'fixed',
          bottom: 30,
          right: 30,
          zIndex: 1001,
          background: '#64ffda',
          color: '#0a192f',
          border: 'none',
          borderRadius: '50%',
          width: 60,
          height: 60,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          boxShadow: '0 4px 8px rgba(0,0,0,0.2)'
        }}
        aria-label="Open Chatbot"
      >
        {/* SVG chat bubble icon */}
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
          <circle cx="12" cy="12" r="10" fill="#0a192f" />
          <path d="M7 10h10M7 14h6" stroke="#64ffda" strokeWidth="2" strokeLinecap="round" />
        </svg>
      </button>
      {/* Chatbot iframe, only visible when open */}
      {open && (
        <div className="chatbot-container">
          <iframe
            src={chatbotUrl}
            title="JotForm Chatbot"
            width="350"
            height="500"
            frameBorder="0"
            allowFullScreen
          />
        </div>
      )}
    </>
  );
}

export default Chatbot;
